              "ESG_PORT_CONTROVERSY_DEF": "The Portfolio Controversy Score is the asset-weighted average level of the seriousness of the controversial incidents of companies in the portfolio. A lower score is better than a higher score, as it indicates fewer controversies. Controversies are represented as: Low, Moderate, Significant, High, or Severe, or None, if there is no evidence of controversy.",
              "ESG_PORT_ESG_DEF": "The Portfolio ESG Score is the asset-weighted average of the normalized company ESG Scores for the covered holdings in a portfolio. Higher scores are better than lower scores and, at the portfolio level, indicate that a fund has more of its assets invested in companies that score well under Sustainalytics' ESG methodology, which evaluates company preparedness, disclosure. ",
