              "ESG_RATINGS_DEF": "Sustainalytics’ ESG Ratings measure how well companies proactively manage the environmental, social and governance issues that are the most material to their business and provide an assessment of companies’ ability to mitigate ESG risks. The ESG Rating is a quantitative score on a scale of 1-100, based on a balanced scorecard system.",
