              "META_DESC_LIST_MUTUALFUNDS": "Mutual Funds Center - Get investing strategies, data, and mutual fund news in the Yahoo Finance Mutual Fund Center. The Fund Screener surfaces low-cost and top-performing funds for each asset category and provides detailed fund profiles, fund charts, and news on fund manage",
              "META_DESC_LIST_OPTIONS": "Options Tools, Education and News on Yahoo Finance",
