              "META_DESC_LIST_WORLD_INDICES": "View performance of all the major world indices.",
              "META_DESC_MULTIQUOTE": "View and compare {quotes} on Yahoo Finance.",
              "META_DESC_PERSONAL_FINANCE": "Read latest personal finance articles about loans, saving & spending, lifestyle, insurance, taxes, career & education, retirement, and real estate. Try our calculators for setting your savings goals for a car, down payment for a home, education and other needs as well as mortgage calculator to determine monthly payments for a home. Search glossary to better understand financial terms and their meanings.",
              "META_DESC_PORTFOLIO": "At Yahoo Finance, you get free stock quotes, up-to-date news, portfolio management resources, international market data, social interaction and mortgage rates that help you manage your financial life.",
              "META_DESC_QUOTE_ANALYSIS": "See stock analyst recommendations for {shortName} ({symbol}), including history of rankings (upgrades, downgrades).",
              "META_DESC_QUOTE_BALANCE-SHEET": "Get the detailed balance sheet for {shortName} ({symbol}). Check out the financial snapshot for possessions, debts and capital invested at a particular date.",
              "META_DESC_QUOTE_CASH-FLOW": "Understand the cash flow statement for {shortName} ({symbol}), learn where the money comes from and how the company spends it.",
              "META_DESC_QUOTE_CHART": "Interactive Chart for {shortName} ({symbol}), analyze all the data with a huge range of indicators.",
              "META_DESC_QUOTE_COMMUNITY": "Welcome to largest financial internet forum where people can hold conversations related to stock trading and investing in equities. You can share your opinion and views on various topics from exciting world of finance.",
              "META_DESC_QUOTE_COMPONENTS": "View the basic {symbol} stock chart on Yahoo Finance and learn which stocks are present under {shortName} ({symbol}).",
              "META_DESC_QUOTE_FINANCIALS": "Get the detailed quarterly/annual income statement for {shortName} ({symbol}). Find out the revenue, expenses and profit or loss over the last fiscal year.",
              "META_DESC_QUOTE_FUTURES": "Yahoo Finance is a leading financial destination, providing consumers with a broad range of comprehensive online financial services and information essential to managing one's financial life. By providing access to up-to-date, international market data, real-time stock quotes, portfolio management resources, and community tools such as message boards and clubs, Yahoo Finance empowers consumers to make well-informed investment decisions.",
              "META_DESC_QUOTE_HISTORY": "Discover historical prices for {symbol} stock on Yahoo Finance. View daily, weekly or monthly format back to when {shortName} stock was issued.",
              "META_DESC_QUOTE_HOLDERS": "Find out the direct holders, institutional holders and mutual fund holders for {shortName} ({symbol}).",
              "META_DESC_QUOTE_HOLDINGS": "View Top Holdings and Key Holding Information for {shortName} ({symbol}).",
              "META_DESC_QUOTE_INSIDER-ROSTER": "Get the latest updated list of insiders for {shortName} ({symbol}). Find out the total of insider shares held, purchased and sold.",
              "META_DESC_QUOTE_INSIDER-TRANSACTIONS": "Get the latest insider transactions for {shortName} ({symbol}). Find out the total of insider shares held, purchased and sold.",
              "META_DESC_QUOTE_KEY-STATISTICS": "Find out all the key statistics for {shortName} ({symbol}), including valuation measures, fiscal year financial statistics, trading record, share statistics and more.",
              "META_DESC_QUOTE_NEWS": "Find out the latest news headlines for {shortName} ({symbol}).",
              "META_DESC_QUOTE_OPTIONS": "View the basic {symbol} option chain and compare options of {shortName} on Yahoo Finance.",
              "META_DESC_QUOTE_PERFORMANCE": "Current and Historical Performance Performance for {shortName} on Yahoo Finance.",
